/**
 * One-time seed data exported from the Python bot's PostgreSQL database.
 *
 * THIS FILE IS TEMPORARY. Once the import has run against the live subreddit,
 * delete src/server/seed/ entirely and redeploy. It exists only to carry
 * history across the cutover, and it is by far the largest thing in the bundle.
 *
 * Timestamps are epoch milliseconds, corrected from the export's PDT values.
 * Authors and clans are newline-delimited strings rather than JSON arrays
 * purely to keep the bundle smaller.
 */

export type SeedPost = {
  /** postId, without the t3_ prefix */
  i: string
  /** created, epoch ms */
  t: number
  /** category */
  c: string
  /** clanTag, null for Searching posts */
  g: string | null
  /** author */
  a: string
  /** tracked: 0 for posts that were removed */
  k: 0 | 1
}

